from collections import deque

def find_regions(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    regions = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r, c) not in visited:
                region = []
                q = deque([(r, c)])
                while q:
                    cr, cc = q.popleft()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    region.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
                            q.append((nr, nc))
                regions.append(region)
    return regions

