import os
import json

def find_nested_data(directory, target_shape=None):
    """Recursively search for JSON data with target shape"""
    results = []
    extension_map = {'.json': 'json', '.jsonl': 'jsonl', '.txt': 'text', '.py': 'python'}

    def walk(path):
        try:
            entries = os.listdir(path)
        except PermissionError:
            return

        for entry in entries:
            entry_path = os.path.join(path, entry)
            if os.path.isdir(entry_path):
                walk(entry_path)
            else:
                if '.' in entry:
                    ext = os.path.splitext(entry)[1]
                    if callable(extension_map.get(ext, None)):
                        try:
                            with open(entry_path, 'r') as f:
                                if ext == '.jsonl':
                                    lines = f.readlines()
                                    for line in lines[:3]:
                                        try:
                                            data = json.loads(line)
                                            if isinstance(data, list) and target_shape:
                                                if len(data) == target_shape[0] and len(data[0]) == target_shape[1]:
                                                    results.append((entry_path, 'jsonl'))
                                        except:
                                            pass
                                elif ext == '.json':
                                    data = json.load(f)
                                    if isinstance(data, list) and target_shape:
                                        if isinstance(data[0], list):
                                            if len(data) == target_shape[0] and len(data[0]) == target_shape[1] + 1 and 'action' in data.get('grid', []) if 'action' in data else False:
                                                pass
                                    if isinstance(data, list) and target_shape:
                                        if isinstance(data[0], list):
                                            h, w = len(data), len(data[0])
                                            if h == target_shape[0] and w == target_shape[1]:
                                                results.append((entry_path, ext))
                        except Exception as e:
                            pass

    walk(directory)
    return results

